#!/usr/bin/env bash
# Run the std::collections tests: tests/std_collections/run.sh [--rcc PATH] [PATTERN]
# Each NAME.rs is built with rcc and its stdout compared with NAME.expected
# (generated by real rustc: rustc --edition 2021 -C opt-level=1
#  -C debug-assertions=off -C overflow-checks=off NAME.rs).
set -u
DIR=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$DIR/../.." && pwd)
RCC="$ROOT/build/rcc"
[ "${1:-}" = "--rcc" ] && { RCC=$2; shift 2; }
PAT=${1:-}
OUT="$ROOT/build/test-work/std_collections"
mkdir -p "$OUT"
pass=0; fail=0
for f in "$DIR"/*.rs; do
  n=$(basename "$f" .rs)
  case "$n" in *"$PAT"*) ;; *) continue ;; esac
  if ! "$RCC" "$f" -o "$OUT/$n" > "$OUT/$n.log" 2>&1; then
    echo "COMPILE_FAIL $n: $(grep -m1 -i -E 'error|fatal' "$OUT/$n.log")"; fail=$((fail+1)); continue
  fi
  ( cd "$OUT" && perl -e 'alarm 60; exec @ARGV' "./$n" > "$OUT/$n.out" 2> "$OUT/$n.err" )
  st=$?
  if [ $st -ne 0 ] || ! cmp -s "$OUT/$n.out" "$DIR/$n.expected"; then
    echo "RUN_FAIL $n (exit $st): $(diff "$DIR/$n.expected" "$OUT/$n.out" | head -3 | tr '\n' ' ')"; fail=$((fail+1))
  else
    pass=$((pass+1))
  fi
done
echo "std_collections: $pass passed, $fail failed"
[ $fail -eq 0 ]
